"""Опыт «ссылка или копия» со страницы 1.2 — то, что показывает интерактив, скриптом.

Запуск: python refs_demo.py
Ожидаемый вывод записан в конце файла.
"""
import copy

# 1. Присваивание: два имени, один объект
a = [1200, 850, 2300]
b = a
a.append(990)
print("1. b = a, потом a.append(990)")
print("   b =", b, "| a is b:", a is b)

# 2. Копия: у каждого имени свой объект. То же дают a[:] и list(a)
a = [1200, 850, 2300]
b = a.copy()
a.append(990)
print("2. b = a.copy(), потом a.append(990)")
print("   b =", b, "| a is b:", a is b)

# 3. Изменение через второе имя видно через первое
a = [1200, 850, 2300]
b = a
b[0] = 1300
print("3. b = a, потом b[0] = 1300")
print("   a =", a)

# 4. Кортеж изменить нельзя: += собирает новый кортеж и переставляет на него имя a
a = (1200, 850, 2300)
b = a
a += (990,)
print("4. кортеж: b = a, потом a += (990,)")
print("   a =", a, "| b =", b, "| a is b:", a is b)

# 5. У списка a += [...] меняет общий объект, а a = a + [...] создаёт новый
a = [1200, 850, 2300]
b = a
a += [990]
print("5. список: a += [990]     → b =", b, "| a is b:", a is b)
a = [1200, 850, 2300]
b = a
a = a + [990]
print("   список: a = a + [990]  → b =", b, "| a is b:", a is b)

# 6. Поверхностная копия: внешний список новый, вложенные списки общие
rows = [[1200, "Сова"], [850, "Кедр"]]
c = rows[:]
c.append([640, "Луч"])       # состав копии меняется отдельно
c[0][0] = 0                  # а вложенный список — общий
print("6. c = rows[:], потом c.append(…) и c[0][0] = 0")
print("   rows =", rows)

# 7. Глубокая копия: независима вся структура
rows = [[1200, "Сова"], [850, "Кедр"]]
d = copy.deepcopy(rows)
d[0][0] = 0
print("7. d = copy.deepcopy(rows), потом d[0][0] = 0")
print("   rows =", rows)

# Вывод:
# 1. b = a, потом a.append(990)
#    b = [1200, 850, 2300, 990] | a is b: True
# 2. b = a.copy(), потом a.append(990)
#    b = [1200, 850, 2300] | a is b: False
# 3. b = a, потом b[0] = 1300
#    a = [1300, 850, 2300]
# 4. кортеж: b = a, потом a += (990,)
#    a = (1200, 850, 2300, 990) | b = (1200, 850, 2300) | a is b: False
# 5. список: a += [990]     → b = [1200, 850, 2300, 990] | a is b: True
#    список: a = a + [990]  → b = [1200, 850, 2300] | a is b: False
# 6. c = rows[:], потом c.append(…) и c[0][0] = 0
#    rows = [[0, 'Сова'], [850, 'Кедр']]
# 7. d = copy.deepcopy(rows), потом d[0][0] = 0
#    rows = [[1200, 'Сова'], [850, 'Кедр']]
